tests:
def test_successful_codes():
    codes = [200, 404, 200, 500, 301, 200, 403]
    assert successful_codes(codes) == [200, 200, 200], "должны остаться только коды из диапазона [200; 299]"


def test_successful_codes_empty():
    assert successful_codes([404, 500, 301]) == [], "если успешных кодов нет, должен вернуться пустой список"


def test_format_errors_with_index():
    codes = [200, 404, 200, 500, 301, 200, 403]
    result = format_errors_with_index(codes)
    assert result == ["1: 404", "3: 500", "6: 403"], f"ожидались строки с индексом и кодом >= 400, получено {result}"


def test_format_errors_with_index_none():
    assert format_errors_with_index([200, 201, 204]) == [], "если ошибок нет, список должен быть пустым"
